"""Seating rows built from a class list."""

from typing import List

from rosterkit.models import Student


def _sort_key(student: Student) -> tuple:
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _check(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ValueError(f"bad seat count: {seats}")
    if not students:
        raise ValueError("no students to seat")


def _chunks(names: List[str], size: int) -> List[List[str]]:
    starts = range(0, len(names), size)
    return [names[idx:idx + size] for idx in starts]


def _line(number: int, names: List[str]) -> str:
    return f"Row {number}: " + " | ".join(names)


# ---
def seat_rows(
    students: List[Student], seats: int
) -> List[str]:
    """Sort by last name, then fill rows in order."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    names = [item.display_name for item in ordered]
    rows = _chunks(names, seats)
    return [_line(*pair) for pair in enumerate(rows, 1)]

