# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student("id-" + last, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make_student("Halloway", "Juno"),
            make_student("Quillon", "Ada"),
            make_student("Dunmere", "Piet")
        ]

    def test_sorted_and_grouped(self):
        self.assertEqual(
            seat_rows(self.pupils, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Ada"
            ]
        )

    def test_single_row_when_seats_exceed_count(self):
        lines = seat_rows(self.pupils, 10)
        self.assertEqual(len(lines), 1)

    def test_ties_break_on_first_name(self):
        pupils = [
            make_student("Roe", "Zed"),
            make_student("Roe", "Abe")
        ]
        line = seat_rows(pupils, 2)[0]
        self.assertEqual(line, "Row 1: Roe, Abe | Roe, Zed")

    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            seat_rows(self.pupils, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            seat_rows(self.pupils, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
